package com.example.platform.studio.storyboard;
import com.example.platform.studio.identity.*;import com.example.platform.studio.reference.StudioVersionPin;import com.example.platform.studio.serialization.CanonicalJson;import java.util.*;
public record StoryboardPanel(StoryboardPanelId id,StudioVersionPin<ShotId,ShotVersionId>shotPin,String annotation,StudioVersionPin<?,?>cameraPlanPin,PanelImage image){
public StoryboardPanel{if(id==null||shotPin==null||image==null)throw new IllegalArgumentException("panel fields are required");annotation=CanonicalJson.requiredText(annotation,"panel annotation");if(annotation.length()>500||annotation.matches("(?is).*(exec|script|command|--|://).*"))throw new IllegalArgumentException("panel annotation violates safe semantic contract");if(cameraPlanPin!=null&&cameraPlanPin.kind()!=StudioVersionPin.AggregateKind.CAMERA_PLAN)throw new IllegalArgumentException("camera plan pin kind mismatch");}
public String canonicalJson(){Map<String,String>m=new LinkedHashMap<>();m.put("annotation",CanonicalJson.quote(annotation));if(cameraPlanPin!=null)m.put("cameraPlanPin",cameraPlanPin.canonicalJson());m.put("id",CanonicalJson.quote(id.value()));m.put("image",image.canonicalJson());m.put("shotPin",shotPin.canonicalJson());return CanonicalJson.object(m);}}
